### Python

```python
import sys
import math
from bisect import bisect_left, bisect_right

LIMIT = 2 * 10**9
MAXN = 2000000

# ---------------- 筛法部分 ----------------
is_prime = [True] * (MAXN + 1)
pi_small = [0] * (MAXN + 1)
primes = []

def sieve():
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(MAXN ** 0.5) + 1):
        if is_prime[i]:
            step = i
            start = i * i
            for j in range(start, MAXN + 1, step):
                is_prime[j] = False
    cnt = 0
    for i in range(2, MAXN + 1):
        if is_prime[i]:
            primes.append(i)
            cnt += 1
        pi_small[i] = cnt

sieve()

# ---------------- Lehmer Pi 记忆化部分 ----------------
phi_memo = {}
lehmer_memo = {}

def phi(x, s):
    if s == 0:
        return x
    if s == 1:
        return x - x // 2
    if s == 2:
        return x - x // 2 - x // 3 + x // 6
    key = (x << 6) | s
    if key in phi_memo:
        return phi_memo[key]
    res = phi(x, s - 1) - phi(x // primes[s - 1], s - 1)
    phi_memo[key] = res
    return res

def icbrt(x):
    """整数立方根"""
    y = int(round(x ** (1/3)))
    while (y + 1) ** 3 <= x:
        y += 1
    while y ** 3 > x:
        y -= 1
    return y

def prime_pi(x):
    if x < MAXN:
        return pi_small[x]
    if x in lehmer_memo:
        return lehmer_memo[x]

    a = prime_pi(int(x ** 0.25))
    b = prime_pi(int(x ** 0.5))
    c = prime_pi(icbrt(x))

    res = phi(x, a) + (b + a - 2) * (b - a + 1) // 2

    for i in range(a + 1, b + 1):
        w = x // primes[i - 1]
        res -= prime_pi(w)
        if i <= c:
            lim = prime_pi(int(w ** 0.5))
            for j in range(i, lim + 1):
                res -= prime_pi(w // primes[j - 1]) - (j - 1)

    lehmer_memo[x] = res
    return res

# ---------------- 特殊素数幂预处理 ----------------
extra_star = []
exponents = [2, 4, 6, 10, 12, 16, 18, 22, 28, 30]

def build_extra():
    max_base = int(LIMIT ** 0.5)
    tmp = set()
    for p in primes:
        if p > max_base:
            break
        for a in exponents:
            val = 1
            ok = True
            for _ in range(a):
                if val > LIMIT // p:
                    ok = False
                    break
                val *= p
            if not ok:
                break
            tmp.add(val)
    extra_star.extend(sorted(tmp))

build_extra()

# ---------------- 区间星数统计 ----------------
def count_stars(l, r):
    # 素数个数 (a=1)
    ans = prime_pi(r) - prime_pi(l - 1)
    # 特殊素数幂个数 (a>=2)
    lo = bisect_left(extra_star, l)
    hi = bisect_right(extra_star, r)
    ans += hi - lo
    return ans

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    out = []
    idx = 1
    for _ in range(t):
        l = int(data[idx])
        r = int(data[idx + 1])
        idx += 2
        out.append(str(count_stars(l, r)))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.*;
import java.util.*;

public class Main {
    static final long LIMIT = 2000000000L;
    static final int MAXN = 2000000;

    static boolean[] isPrime = new boolean[MAXN + 1];
    static int[] piSmall = new int[MAXN + 1];
    static ArrayList<Integer> primes = new ArrayList<>();
    static ArrayList<Long> extraStar = new ArrayList<>();

    static HashMap<Long, Long> phiMemo = new HashMap<>();
    static HashMap<Long, Long> lehmerMemo = new HashMap<>();

    static void sieve() {
        Arrays.fill(isPrime, true);
        isPrime[0] = isPrime[1] = false;
        for (int i = 2; (long) i * i <= MAXN; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= MAXN; j += i) {
                    isPrime[j] = false;
                }
            }
        }
        int cnt = 0;
        for (int i = 2; i <= MAXN; i++) {
            if (isPrime[i]) {
                primes.add(i);
                cnt++;
            }
            piSmall[i] = cnt;
        }
    }

    static long phi(long x, int s) {
        if (s == 0) return x;
        if (s == 1) return x - x / 2;
        if (s == 2) return x - x / 2 - x / 3 + x / 6;
        long key = (x << 6) | s;
        Long val = phiMemo.get(key);
        if (val != null) return val;
        long res = phi(x, s - 1) - phi(x / primes.get(s - 1), s - 1);
        phiMemo.put(key, res);
        return res;
    }

    static long icbrt(long x) {
        long y = (long) Math.round(Math.cbrt(x));
        while ((y + 1) * (y + 1) * (y + 1) <= x) y++;
        while (y * y * y > x) y--;
        return y;
    }

    static long primePi(long x) {
        if (x < MAXN) return piSmall[(int) x];
        Long val = lehmerMemo.get(x);
        if (val != null) return val;

        int a = (int) primePi((long) Math.sqrt(Math.sqrt(x)));
        int b = (int) primePi((long) Math.sqrt(x));
        int c = (int) primePi(icbrt(x));

        long res = phi(x, a) + ((long) (b + a - 2) * (b - a + 1)) / 2;

        for (int i = a + 1; i <= b; i++) {
            long w = x / primes.get(i - 1);
            res -= primePi(w);
            if (i <= c) {
                int lim = (int) primePi((long) Math.sqrt(w));
                for (int j = i; j <= lim; j++) {
                    res -= primePi(w / primes.get(j - 1)) - (j - 1);
                }
            }
        }

        lehmerMemo.put(x, res);
        return res;
    }

    static void buildExtra() {
        int[] exponents = {2, 4, 6, 10, 12, 16, 18, 22, 28, 30};
        long maxBase = (long) Math.sqrt(LIMIT);
        TreeSet<Long> set = new TreeSet<>();
        for (int p : primes) {
            if (p > maxBase) break;
            for (int a : exponents) {
                long v = 1;
                boolean ok = true;
                for (int i = 0; i < a; i++) {
                    if (v > LIMIT / p) {
                        ok = false;
                        break;
                    }
                    v *= p;
                }
                if (!ok) break;
                set.add(v);
            }
        }
        extraStar.addAll(set);
    }

    static int lowerBound(ArrayList<Long> list, long target) {
        int l = 0, r = list.size();
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (list.get(mid) >= target) r = mid;
            else l = mid + 1;
        }
        return l;
    }

    static int upperBound(ArrayList<Long> list, long target) {
        int l = 0, r = list.size();
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (list.get(mid) > target) r = mid;
            else l = mid + 1;
        }
        return l;
    }

    static long countStars(long l, long r) {
        long ans = primePi(r) - primePi(l - 1);
        ans += upperBound(extraStar, r) - lowerBound(extraStar, l);
        return ans;
    }

    public static void main(String[] args) throws Exception {
        sieve();
        buildExtra();

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();

        while (T-- > 0) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            long l = Long.parseLong(st.nextToken());
            long r = Long.parseLong(st.nextToken());
            sb.append(countStars(l, r)).append('\n');
        }

        System.out.print(sb.toString());
    }
}
