### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

const long long LIMIT = 2000000000LL;
const int MAXN = 2000000;

vector<int> primes;
vector<int> piSmall(MAXN + 1);
vector<bool> isPrime(MAXN + 1, true);
vector<long long> extraStar;

unordered_map<unsigned long long, long long> phiMemo;
unordered_map<long long, long long> lehmerMemo;

void sieve() {
    isPrime[0] = isPrime[1] = false;
    for (int i = 2; 1LL * i * i <= MAXN; i++) {
        if (isPrime[i]) {
            for (int j = i * i; j <= MAXN; j += i) {
                isPrime[j] = false;
            }
        }
    }
    int cnt = 0;
    for (int i = 2; i <= MAXN; i++) {
        if (isPrime[i]) {
            primes.push_back(i);
            cnt++;
        }
        piSmall[i] = cnt;
    }
}

long long phi(long long x, int s) {
    if (s == 0) return x;
    if (s == 1) return x - x / 2;
    if (s == 2) return x - x / 2 - x / 3 + x / 6;
    unsigned long long key = (unsigned long long)x * 64ULL + (unsigned long long)s;
    auto it = phiMemo.find(key);
    if (it != phiMemo.end()) return it->second;
    long long res = phi(x, s - 1) - phi(x / primes[s - 1], s - 1);
    phiMemo[key] = res;
    return res;
}

long long icbrt(long long x) {
    long long y = round(cbrt((long double)x));
    while ((y + 1) * 1LL * (y + 1) * (y + 1) <= x) y++;
    while (y * 1LL * y * y > x) y--;
    return y;
}

long long primePi(long long x) {
    if (x < MAXN) return piSmall[(int)x];
    auto it = lehmerMemo.find(x);
    if (it != lehmerMemo.end()) return it->second;

    int a = (int)primePi(sqrt(sqrt((long double)x)));
    int b = (int)primePi(sqrt((long double)x));
    int c = (int)primePi(icbrt(x));

    long long res = phi(x, a) + 1LL * (b + a - 2) * (b - a + 1) / 2;

    for (int i = a + 1; i <= b; i++) {
        long long w = x / primes[i - 1];
        res -= primePi(w);
        if (i <= c) {
            int lim = (int)primePi(sqrt((long double)w));
            for (int j = i; j <= lim; j++) {
                res -= primePi(w / primes[j - 1]) - (j - 1);
            }
        }
    }

    lehmerMemo[x] = res;
    return res;
}

void buildExtra() {
    vector<int> exponents = {2, 4, 6, 10, 12, 16, 18, 22, 28, 30};
    long long maxBase = sqrt((long double)LIMIT);
    set<long long> st;
    for (int p : primes) {
        if (p > maxBase) break;
        for (int a : exponents) {
            long long v = 1;
            bool ok = true;
            for (int i = 0; i < a; i++) {
                if (v > LIMIT / p) {
                    ok = false;
                    break;
                }
                v *= p;
            }
            if (!ok) break;
            st.insert(v);
        }
    }
    extraStar.assign(st.begin(), st.end());
}

long long countStars(long long l, long long r) {
    long long ans = primePi(r) - primePi(l - 1);
    ans += upper_bound(extraStar.begin(), extraStar.end(), r)
         - lower_bound(extraStar.begin(), extraStar.end(), l);
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    sieve();
    buildExtra();

    int T;
    cin >> T;
    while (T--) {
        long long l, r;
        cin >> l >> r;
        cout << countStars(l, r) << '\n';
    }
    return 0;
}
